function named(map,v){return v===null||v===undefined?'unavailable':`${map[v]??'code'} (${v})`}
function fmt(v,d=2,u=''){return Number.isFinite(v)?v.toFixed(d)+(u?' '+u:''):'unavailable'}
function boardNumber(serial){if(!serial)return 'ODrive ?';const h=lastHardware||{};const list=[...new Set([...(h.discovered?.boards||[]).map(b=>b.serial),h.profile?.test_serial,h.profile?.load_serial].filter(Boolean))].sort();return 'ODrive '+(list.indexOf(serial)+1)}
function kvRows(rows){return rows.map(([k,v,alert])=>`<tr class="${alert?'alert':''}"><th>${esc(k)}</th><td>${esc(v)}</td></tr>`).join('')}
function dashRows(b,fresh){const s=fresh&&b.connected?b.signals:{},c=b.configuration||{},e=b.errors||{};const faulted=[e.active_errors,e.disarm_reason].some(v=>v!==0&&v!==null&&v!==undefined);
 return kvRows([['Board',`${boardNumber(b.serial)} · ${b.serial||'not assigned'}`],['Connection / axis state',b.connected?(fresh?b.state:'STALE DATA'):'DISCONNECTED',b.connected&&!fresh],['Feedback source',b.feedback_method||'unavailable'],
 ['Control / input mode',named(CONTROL_MODES,c['axis0.controller.config.control_mode'])+' / '+named(INPUT_MODES,c['axis0.controller.config.input_mode'])],
 ['Speed: reference / measured',(c['axis0.controller.config.control_mode']===2?fmt(s.speed_setpoint_rpm??s.speed_command_rpm,1):'n/a (not velocity control)')+' / '+fmt(s.speed_rpm,1)+' rpm'],['Speed error',c['axis0.controller.config.control_mode']===2?fmt(s.speed_error_rpm,2,'rpm'):'n/a (not velocity control)'],
 ['Iq: reference / measured',fmt(s.iq_command_a,3)+' / '+fmt(s.iq_a,3)+' A'],['Iq tracking error',fmt(s.iq_error_a,3,'A')],['Id measured',fmt(s.id_a,3,'A')],
 ['Torque estimate (configured Kt × Iq)',fmt(s.torque_nm,3,'N·m')],['Selected-feedback position / speed',fmt(s.position_turns,3,'turn')+' / '+fmt(s.speed_rpm,1,'rpm')],
 ['Independent encoder speed (if verified)',fmt(s.encoder_speed_rpm,1,'rpm')],['Sensorless estimate: speed / electrical phase',fmt(s.sensorless_speed_rpm,1,'rpm')+' / '+fmt(s.estimated_electrical_rad,2,'rad')],
 ['DC bus: voltage / current',fmt(s.dc_voltage_v,2,'V')+' / '+fmt(s.dc_current_a,2,'A')],['Electrical input power (V × I)',fmt(s.electrical_power_w,1,'W')],
 ['Temperature: motor / controller',fmt(s.motor_temp_c,1,'°C')+' / '+fmt(s.controller_temp_c,1,'°C')],
 ['Active errors / disarm reason',`${e.active_errors??'unavailable'} / ${e.disarm_reason??'unavailable'}`,faulted],['Last procedure result',named(PROCEDURES,b.procedure_result)]])}
